<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/whatsapp.php';
$user=require_role('admin','staf_bkk');
$filters=wa_filters($_GET);$contacts=wa_contacts($filters);$total=count($contacts);
$pages=max(1,(int)ceil($total/20));$page=min($pages,positive_id($_GET['page']??'1')??1);$rows=array_slice($contacts,($page-1)*20,20);
$jobs=panel_query('SELECT DISTINCT lowongan_id,posisi,perusahaan FROM lamaran ORDER BY posisi,perusahaan')->fetchAll();
if(!empty($_SESSION['wa_create_key']) && panel_query('SELECT id FROM wa_campaigns WHERE submission_key=:key',['key'=>$_SESSION['wa_create_key']])->fetchColumn()){unset($_SESSION['wa_create_key']);}
if(empty($_SESSION['wa_create_key'])){$_SESSION['wa_create_key']=bin2hex(random_bytes(32));}
$draft=$_SESSION['wa_draft']??['judul'=>'','pesan'=>'Halo {nama}, ada informasi lowongan dari BKK SMK Jaya Buana.','tautan'=>''];unset($_SESSION['wa_draft']);
$historyPage=positive_id($_GET['history_page']??'1')??1;
$historyTotal=(int)panel_query('SELECT COUNT(*) FROM wa_campaigns')->fetchColumn();$historyPages=max(1,(int)ceil($historyTotal/10));$historyPage=min($historyPages,$historyPage);
$history=panel_query('SELECT c.id,c.judul,c.created_at,COUNT(r.id) AS total,SUM(r.opened_at IS NOT NULL) AS opened,SUM(r.marked_at IS NOT NULL) AS marked FROM wa_campaigns c LEFT JOIN wa_recipients r ON r.campaign_id=c.id GROUP BY c.id ORDER BY c.id DESC LIMIT 10 OFFSET :offset',['offset'=>($historyPage-1)*10])->fetchAll();
panel_start($user,'Pesan WhatsApp','whatsapp');
?>
<div class="content-management wa-page"><div class="page-actions"><h1><?= panel_icon('whatsapp') ?> Pesan WhatsApp</h1></div>
<p class="notice">Pilih penerima, siapkan pesan, lalu buka WhatsApp satu per satu. Anda tetap menekan Kirim di WhatsApp. Riwayat tidak memastikan pesan terkirim atau dibaca.</p>
<form method="get" class="filter-form card"><label>Kelompok<select name="group"><?php foreach(['pelamar'=>'Pelamar','tracer'=>'Alumni mencari kerja','semua'=>'Pelamar dan alumni mencari kerja'] as $value=>$label):?><option value="<?= $value ?>" <?= $filters['group']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label>Lowongan pelamar<select name="lowongan"><option value="">Semua lowongan</option><?php foreach($jobs as $job):?><option value="<?= (int)$job['lowongan_id'] ?>" <?= $filters['lowongan']===(int)$job['lowongan_id']?'selected':'' ?>><?= e($job['posisi'].' - '.$job['perusahaan']) ?></option><?php endforeach;?></select></label><label>Nama / nomor<input type="search" name="q" value="<?= e($filters['q']) ?>" maxlength="100"></label><button type="submit">Tampilkan</button></form>
<p><?= $total ?> nomor unik dengan persetujuan WhatsApp. Data lama tanpa persetujuan tidak disertakan. Alumni memakai status Tracer Study terbaru.</p>
<form method="post" action="<?= e(base_url('panel/whatsapp/buat.php')) ?>" class="wa-compose">
<?= csrf_field() ?><input type="hidden" name="submission_key" value="<?= e($_SESSION['wa_create_key']) ?>"><?php foreach($filters as $key=>$value):?><input type="hidden" name="<?= $key ?>" value="<?= e((string)$value) ?>"><?php endforeach;?>
<section class="card"><h2><?= panel_icon('pengguna') ?> Penerima</h2><div class="wa-selection"><label><input type="radio" name="mode" value="all" checked> Semua <?= $total ?> nomor sesuai filter</label><label><input type="radio" name="mode" value="manual"> Hanya yang dicentang pada halaman ini</label></div>
<div class="table-scroll" tabindex="0" aria-label="Daftar calon penerima"><table><thead><tr><th>Pilih</th><th>Nama</th><th>WhatsApp</th><th>Sumber</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><input type="checkbox" name="selected[]" value="<?= e($row['key']) ?>" aria-label="<?= e('Pilih '.$row['nama']) ?>"></td><td><?= e($row['nama']) ?></td><td><?= e($row['nomor']) ?></td><td><?= e($row['sumber']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">Belum ada penerima yang sesuai dan memberikan persetujuan.</td></tr><?php endif;?></tbody></table></div>
<?php if($pages>1):?><nav class="pagination" aria-label="Halaman penerima"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;}?><a href="<?= e(base_url('panel/whatsapp/?'.http_build_query($filters+['page'=>$target]))) ?>"><?= $label ?></a><?php endforeach;?></nav><p class="muted">Halaman <?= $page ?>/<?= $pages ?>. Pilihan manual berlaku pada halaman ini. Berpindah halaman mengosongkan isian pesan dan centang penerima.</p><?php endif;?></section>
<section class="card editor-form"><h2><?= panel_icon('message') ?> Susun pesan</h2><label for="wa-title">Judul catatan<input id="wa-title" name="judul" maxlength="150" value="<?= e($draft['judul']) ?>" required></label><label for="wa-message">Pesan<textarea id="wa-message" name="pesan" rows="7" maxlength="1500" required><?= e($draft['pesan']) ?></textarea></label><small>Gunakan {nama} untuk nama penerima otomatis. Pesan disiapkan setelah daftar dibuat.</small><label for="wa-link">Tautan informasi / poster (opsional)<input id="wa-link" name="tautan" type="url" maxlength="2048" placeholder="https://..." value="<?= e($draft['tautan']) ?>"></label><small>Gunakan tautan publik yang dapat diakses penerima. Berkas lampiran ditambahkan manual di WhatsApp.</small><button type="submit" <?= !$total?'disabled':'' ?>><?= panel_icon('whatsapp') ?> Siapkan daftar pesan</button></section></form>
<section class="wa-history"><h2>Riwayat daftar pesan</h2><div class="table-scroll"><table><thead><tr><th>Judul / dibuat (WIB)</th><th>Penerima</th><th>Dibuka</th><th>Ditandai dikirim</th><th></th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?= e($item['judul']) ?><small><?= e($item['created_at']) ?></small></td><td><?= (int)$item['total'] ?></td><td><?= (int)$item['opened'] ?></td><td><?= (int)$item['marked'] ?></td><td><a href="<?= e(base_url('panel/whatsapp/detail.php?id='.$item['id'])) ?>">Buka daftar</a></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="5">Belum ada daftar pesan.</td></tr><?php endif;?></tbody></table></div>
<?php if($historyPages>1):?><nav class="pagination" aria-label="Halaman riwayat"><?php foreach(['Sebelumnya'=>$historyPage-1,'Berikutnya'=>$historyPage+1] as $label=>$target):if($target<1||$target>$historyPages){continue;}?><a href="<?= e(base_url('panel/whatsapp/?'.http_build_query($filters+['history_page'=>$target]))) ?>"><?= $label ?></a><?php endforeach;?></nav><?php endif;?></section></div>
<?php panel_end($user); ?>
